-- ---------------------------------------------------------------- integrity triggers

CREATE OR REPLACE FUNCTION vms_reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '%', TG_ARGV[0];
END;
$$;

CREATE OR REPLACE FUNCTION vms_guard_report() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.locked_at IS NOT NULL THEN
    RAISE EXCEPTION 'Incident report is locked: approved records cannot be modified';
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'DRAFT' THEN RAISE EXCEPTION 'Only draft incident reports can be deleted'; END IF;
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION vms_guard_report_child() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_report BIGINT; v_locked TIMESTAMPTZ;
BEGIN
  IF TG_OP = 'DELETE' THEN v_report := OLD.report_id; ELSE v_report := NEW.report_id; END IF;
  SELECT locked_at INTO v_locked FROM incident_report WHERE report_id = v_report;
  IF v_locked IS NOT NULL OR (TG_OP = 'UPDATE' AND OLD.report_id <> NEW.report_id) THEN
    RAISE EXCEPTION 'Incident report is locked: approved records cannot be modified';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_incident_report_lock BEFORE UPDATE OR DELETE ON incident_report
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report();

CREATE TRIGGER trg_incident_timeline_lock BEFORE INSERT OR UPDATE OR DELETE ON incident_timeline
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report_child();

CREATE TRIGGER trg_incident_clock_pause_lock BEFORE INSERT OR UPDATE OR DELETE ON incident_clock_pause
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report_child();

CREATE TRIGGER trg_incident_service_state_lock BEFORE INSERT OR UPDATE OR DELETE ON incident_service_state
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report_child();

CREATE TRIGGER trg_vendor_action_lock BEFORE INSERT OR UPDATE OR DELETE ON vendor_action
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report_child();

CREATE TRIGGER trg_incident_sla_result_lock BEFORE INSERT OR UPDATE OR DELETE ON incident_sla_result
  FOR EACH ROW EXECUTE FUNCTION vms_guard_report_child();

CREATE TRIGGER trg_e_signature_append_only BEFORE UPDATE OR DELETE ON e_signature
  FOR EACH ROW EXECUTE FUNCTION vms_reject_change('e_signature is append-only: records cannot be modified or deleted');

CREATE TRIGGER trg_report_document_append_only BEFORE UPDATE OR DELETE ON report_document
  FOR EACH ROW EXECUTE FUNCTION vms_reject_change('report_document is append-only: records cannot be modified or deleted');

CREATE TRIGGER trg_audit_event_append_only BEFORE UPDATE OR DELETE ON audit_event
  FOR EACH ROW EXECUTE FUNCTION vms_reject_change('audit_event is append-only: records cannot be modified or deleted');
